#!/bin/bash
# Read-only facts used for the expected answers in test-questions.md
T=${MB_DEMO_TENANT_ID:?set MB_DEMO_TENANT_ID (tenants.id of G2DEMO)}
q(){ echo "### $1"; "$(dirname "$0")/q.sh" "$2"; }
q "opd today by dept" "select d.name, count(*) from encounters e join departments d on d.id=e.department_id where e.tenant_id='$T' and e.encounter_type='opd' and e.encounter_date=current_date group by 1 order by 2 desc"
q "queue today by status" "select status,count(*) from opd_queues where tenant_id='$T' and queue_date=current_date group by 1 order by 2 desc"
q "queue by doctor" "select u.full_name, count(*) total, count(*) filter (where q.status='waiting') waiting, count(*) filter (where q.status='completed') done, count(*) filter (where q.status='no_show') noshow from opd_queues q join users u on u.id=q.doctor_id where q.tenant_id='$T' and q.queue_date=current_date group by 1 order by 2 desc"
q "htn readings" "select count(*), count(distinct encounter_id) from vitals where tenant_id='$T' and (systolic_bp>=160 or diastolic_bp>=100)"
q "low spo2" "select p.first_name||' '||p.last_name, v.spo2, e.encounter_type from vitals v join encounters e on e.id=v.encounter_id join patients p on p.id=e.patient_id where v.tenant_id='$T' and v.spo2<92 order by v.spo2"
q "top diagnoses" "select icd_code, description, count(*) from diagnoses where tenant_id='$T' group by 1,2 order by 3 desc limit 6"
q "appointments" "select case when appointment_date<current_date then 'past' when appointment_date=current_date then 'today' else 'future' end w, status, appointment_type, count(*) from appointments where tenant_id='$T' group by 1,2,3 order by 1,2"
q "fu next 7 days" "select count(*) from appointments where tenant_id='$T' and appointment_type='follow_up' and status='scheduled' and appointment_date between current_date+1 and current_date+7"
q "tomorrow" "select count(*) from appointments where tenant_id='$T' and appointment_date=current_date+1 and status='scheduled'"
q "penicillin allergy" "select p.uhid,p.first_name||' '||p.last_name,a.reaction,a.severity from patient_allergies a join patients p on p.id=a.patient_id where a.tenant_id='$T' and a.allergen_name ilike 'penicillin%'"
q "abha / kids / no blood group" "select count(*) filter (where abha_number is not null) abha, count(*) filter (where date_of_birth > current_date - interval '14 years') kids, count(*) filter (where blood_group is null) no_bg, count(*) filter (where email is null) no_email, count(*) filter (where gender='female') f from patients where tenant_id='$T'"
q "inpatients by ward" "select w.name, count(*) from admissions a join bed_states b on b.location_id=a.bed_id join wards w on w.id=b.ward_id where a.tenant_id='$T' and a.status='admitted' group by 1"
q "admissions status" "select status, discharge_type, count(*) from admissions where tenant_id='$T' group by 1,2"
q "admissions missing fields" "select p.uhid, p.first_name||' '||p.last_name, a.admission_weight_kg is null no_weight, a.expected_discharge_date is null no_edd, a.admission_source is null no_source, a.bed_id is null no_bed from admissions a join patients p on p.id=a.patient_id where a.tenant_id='$T' and a.status='admitted' and (a.admission_weight_kg is null or a.expected_discharge_date is null or a.admission_source is null)"
q "pending clearance" "select p.uhid,p.first_name||' '||p.last_name, w.discharge_ordered_at is not null ordered, w.bill_closed_at from ipd_discharge_workflows w join admissions a on a.id=w.admission_id join patients p on p.id=a.patient_id where w.tenant_id='$T' and a.status='admitted'"
q "bed transfers" "select count(*) from bed_transfers where tenant_id='$T'"
q "beds" "select status,count(*) from bed_states where tenant_id='$T' group by 1"
q "unacked criticals" "select p.uhid,p.first_name||' '||p.last_name, c.parameter_name,c.value,c.flag from lab_critical_alerts c join patients p on p.id=c.patient_id where c.tenant_id='$T' and c.acknowledged_at is null"
q "criticals all" "select c.parameter_name,c.value,c.flag,count(*) from lab_critical_alerts c where c.tenant_id='$T' group by 1,2,3 order by 1"
q "lab status" "select status,count(*) from lab_orders where tenant_id='$T' group by 1"
q "lab no ranges" "select code from lab_test_catalog where tenant_id='$T' and normal_range is null"
q "rad" "select o.status, count(*) from radiology_orders o where o.tenant_id='$T' group by 1"
q "rad critical" "select p.first_name||' '||p.last_name, r.impression from radiology_reports r join radiology_orders o on o.id=r.order_id join patients p on p.id=o.patient_id where r.tenant_id='$T' and r.is_critical"
q "expiring 30d" "select c.name,b.batch_number,b.expiry_date,b.quantity_on_hand from pharmacy_batches b join pharmacy_catalog c on c.id=b.catalog_item_id where b.tenant_id='$T' and b.expiry_date <= current_date+30 order by 3"
q "low stock" "select code,name,current_stock,reorder_level from pharmacy_catalog where tenant_id='$T' and current_stock<reorder_level order by 3"
q "ndps" "select c.code, r.action, sum(r.quantity) from pharmacy_ndps_register r join pharmacy_catalog c on c.id=r.catalog_item_id where r.tenant_id='$T' group by 1,2 order by 1"
q "ndps stock" "select code,current_stock from pharmacy_catalog where tenant_id='$T' and is_controlled"
q "pharm orders" "select status, dispensing_type, count(*) from pharmacy_orders where tenant_id='$T' group by 1,2"
q "billing today" "select count(*), sum(total_amount), sum(paid_amount), sum(total_amount-paid_amount) from invoices where tenant_id='$T' and status<>'cancelled'"
q "invoice status" "select status,count(*),sum(total_amount),sum(total_amount-paid_amount) bal from invoices where tenant_id='$T' group by 1"
q "payments by mode" "select mode,count(*),sum(amount) from payments where tenant_id='$T' group by 1"
q "outstanding >5000" "select i.invoice_number,p.first_name||' '||p.last_name, i.total_amount, i.paid_amount, i.total_amount-i.paid_amount bal from invoices i join patients p on p.id=i.patient_id where i.tenant_id='$T' and i.status not in ('cancelled','paid') and i.total_amount-i.paid_amount>5000 order by bal desc"
q "refunds" "select refund_number,amount,mode,reason from refunds where tenant_id='$T'"
q "day close" "select close_date,expected_cash,actual_cash,cash_difference,total_card,total_upi from billing_day_closes where tenant_id='$T'"
q "preauths" "select pa.pa_number,p.first_name||' '||p.last_name,pa.status,pa.estimated_cost,pa.approved_amount from prior_auth_requests pa join patients p on p.id=pa.patient_id where pa.tenant_id='$T'"
q "claims" "select p.first_name||' '||p.last_name,c.insurance_provider,c.claim_type,c.status from insurance_claims c join patients p on p.id=c.patient_id where c.tenant_id='$T'"
q "er" "select p.first_name||' '||p.last_name, v.status, v.is_mlc, t.triage_level from er_visits v join patients p on p.id=v.patient_id left join er_triage_assessments t on t.er_visit_id=v.id where v.tenant_id='$T'"
q "mlc" "select mlc_number,case_type,status,police_station from mlc_cases where tenant_id='$T'"
